/// Notification digest
///
/// The marker that a digest was made for a period (NTF-3101), kept as documents of kind notice-digest (crates/backend/src/inbox/digest.rs); its id is the id of the inbox item of the digest and the idempotency key of the mail of it.
///
/// Retention: Until the tenant file is deleted; no sweep removes a marker yet.
///
/// Record `rec-notification-digest`, owned by component `notification-service`, schema version 1.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct RecNotificationDigest {
    /// Derived from the tenant, the person, the category, the channel and the start of the period.
    #[serde(rename = "digest-id")]
    pub digest_id: types::Identifier,
    /// Field `person`.
    ///
    /// Holds a principal id. On delete: cascade.
    ///
    /// Constraints: at most 96 characters, matches `^[A-Za-z0-9_:.-]+$`.
    pub person: types::PrincipalId,
    /// Field `category`.
    pub category: types::MessageCategoryId,
    /// Field `channel`.
    pub channel: types::NotificationChannel,
    /// Field `period-start`.
    #[serde(rename = "period-start")]
    pub period_start: prelude::Timestamp,
    /// Field `made-at`.
    #[serde(rename = "made-at")]
    pub made_at: prelude::Timestamp,
}

/// The key of a [`RecNotificationDigest`]: `digest-id`.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct RecNotificationDigestKey {
    /// Derived from the tenant, the person, the category, the channel and the start of the period.
    #[serde(rename = "digest-id")]
    pub digest_id: types::Identifier,
}

impl RecNotificationDigest {
    /// The record's id in the specification.
    pub const ID: &str = "rec-notification-digest";

    /// The version of the record's stored shape.
    pub const SCHEMA_VERSION: u32 = 1;

    /// The key fields, by their specification names.
    pub const KEY: &[&str] = &["digest-id"];

    /// Sets of fields whose combined values are unique, by their specification names.
    pub const UNIQUE: &[&[&str]] = &[];

    /// The record's indexes.
    pub const INDEXES: &[prelude::Index] = &[];

    /// The fields that hold the key of another record, and what deleting it does.
    pub const REFERENCES: &[prelude::Reference] = &[prelude::Reference {
        field: "person",
        record: "principal",
        on_delete: prelude::OnDelete::Cascade,
    }];

    /// The record's key.
    pub fn key(&self) -> RecNotificationDigestKey {
        RecNotificationDigestKey {
            digest_id: self.digest_id,
        }
    }

    /// Checks the field constraints, returning the first one the record breaks.
    pub fn validate(&self) -> Result<(), prelude::ConstraintViolation> {
        if self.person.0.chars().count() > 96 {
            return Err(prelude::ConstraintViolation {
                record: Self::ID,
                field: "person",
                constraint: prelude::Constraint::MaxLength,
            });
        }
        if !REC_NOTIFICATION_DIGEST_PERSON_PATTERN.is_match(&self.person.0) {
            return Err(prelude::ConstraintViolation {
                record: Self::ID,
                field: "person",
                constraint: prelude::Constraint::Pattern,
            });
        }
        Ok(())
    }
}
